import { LoggerService } from '@backstage/backend-plugin-api';
import { ActionsRegistryService } from '@backstage/backend-plugin-api/alpha';
import { SearchEngine } from '@backstage/plugin-search-backend-node';
import { SearchIndexService } from '@backstage/plugin-search-backend-node/alpha';

/**
 * Determines whether the location of a search result is safe to hand back to a
 * caller. Relative locations (which have no protocol) are always considered
 * safe, while absolute locations are only allowed when they use the `http:` or
 * `https:` protocol. This prevents potentially dangerous protocols such as
 * `javascript:` or `data:` from being surfaced to agents.
 */
function isSafeLocation(location: string): boolean {
  const match = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(location);
  if (!match) {
    // No protocol, e.g. a relative URL such as "/catalog/default/component/foo".
    return true;
  }
  const protocol = match[1].toLowerCase();
  return protocol === 'http' || protocol === 'https';
}

/**
 * Registers a search query action with the provided actions registry, allowing
 * agents to query the search engine.
 */
export function createQueryAction({
  engine,
  actionsRegistry,
  searchIndexService,
  logger,
}: {
  engine: SearchEngine;
  actionsRegistry: ActionsRegistryService;
  searchIndexService: SearchIndexService;
  logger: LoggerService;
}): void {
  const documentTypes = Object.keys(searchIndexService.getDocumentTypes());

  const typesDescription =
    documentTypes.length > 0
      ? `The following document types are available to filter on via the \`types\` field: ${documentTypes
          .map(type => `"${type}"`)
          .join(', ')}.`
      : 'There are currently no document types registered in the search index.';

  actionsRegistry.register({
    name: 'search',
    title: 'Search',
    description: `
Queries the Backstage search engine and returns matching documents.

Each result has a \`type\` (the document type it came from) and a \`document\` with at
least a \`title\`, \`text\`, and \`location\` (the URL where the document can be viewed).

${typesDescription}

## Pagination

Use \`pageLimit\` to control how many results are returned per page. The response
includes \`hasMoreResults\` and, when there are more results, a \`nextPageCursor\`
that can be passed back as \`pageCursor\` to fetch the next page. \`totalItems\`
indicates the total number of matching documents when known.
    `,
    attributes: {
      destructive: false,
      readOnly: true,
      idempotent: true,
    },
    schema: {
      input: z =>
        z.object({
          term: z
            .string()
            .describe('The search term to query the search engine with.'),
          types: z
            .array(z.string())
            .optional()
            .describe(
              'Optional list of document types to restrict the search to.',
            ),
          filters: z
            .record(z.any())
            .optional()
            .describe(
              'Optional set of field filters to apply to the search query.',
            ),
          pageLimit: z
            .number()
            .optional()
            .describe('Maximum number of results to return per page.'),
          pageCursor: z
            .string()
            .optional()
            .describe(
              'Cursor for fetching a specific page of results, obtained from a previous response\'s `nextPageCursor`.',
            ),
        }),
      output: z =>
        z.object({
          results: z
            .array(
              z.object({
                type: z
                  .string()
                  .describe('The type of the document this result came from.'),
                document: z
                  .object({
                    title: z.string(),
                    text: z.string(),
                    location: z.string(),
                  })
                  .passthrough()
                  .describe('The matched document.'),
              }),
            )
            .describe('The list of documents matching the search query.'),
          nextPageCursor: z
            .string()
            .optional()
            .describe(
              'Cursor to pass as `pageCursor` to fetch the next page of results, if any.',
            ),
          totalItems: z
            .number()
            .optional()
            .describe(
              'The total number of documents matching the search query, when known.',
            ),
          hasMoreResults: z
            .boolean()
            .describe('Whether there are more results available.'),
        }),
    },
    action: async ({ input }) => {
      const resultSet = await engine.query({
        term: input.term,
        types: input.types,
        filters: input.filters,
        pageLimit: input.pageLimit,
        pageCursor: input.pageCursor,
      });

      const results = [];
      for (const result of resultSet.results) {
        const { authorization, ...document } = result.document as {
          [key: string]: any;
          title: string;
          text: string;
          location: string;
        };

        if (!isSafeLocation(document.location)) {
          logger.info(
            `Excluding search result with unsafe location "${document.location}"`,
          );
          continue;
        }

        results.push({
          type: result.type,
          document,
        });
      }

      return {
        output: {
          results,
          nextPageCursor: resultSet.nextPageCursor,
          totalItems: resultSet.numberOfResults,
          hasMoreResults: Boolean(resultSet.nextPageCursor),
        },
      };
    },
  });
}
