describe('createQueryAction scratch', () => {
  it('registers with empty document types and forwards input', async () => {
    const { actionsRegistry, engine } = setup(async () => ({
      results: [
        { type: 't', document: { title: 'a', text: 'b', location: '/x', authorization: { foo: 1 } } },
      ],
      nextPageCursor: 'next',
      numberOfResults: 42,
    }));

